package vn.covie.realtime; import java.io.IOException; import java.util.*; import java.util.concurrent.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@Component public class SseConnectionRegistry {private final long timeout;private final ConcurrentMap<UUID,Set<SseEmitter>> connections=new ConcurrentHashMap<>();public SseConnectionRegistry(@Value("${covie.sse.emitter-timeout-ms:1800000}")long timeout){this.timeout=timeout;}public SseEmitter register(UUID userId){SseEmitter emitter=new SseEmitter(timeout);connections.computeIfAbsent(userId,_ -> ConcurrentHashMap.newKeySet()).add(emitter);Runnable remove=()->remove(userId,emitter);emitter.onCompletion(remove);emitter.onTimeout(remove);emitter.onError(_ -> remove.run());send(emitter,"sync-required",Map.of());return emitter;}public void publish(SseSignal signal){for(SseEmitter e:List.copyOf(connections.getOrDefault(signal.userId(),Set.of())))send(e,signal.eventName(),signal.data());}public void heartbeat(){connections.forEach((user,emitters)->List.copyOf(emitters).forEach(e->{try{e.send(SseEmitter.event().comment("keepalive"));}catch(IOException|IllegalStateException ex){remove(user,e);}}));}private void send(SseEmitter e,String event,Map<String,Object> data){try{e.send(SseEmitter.event().name(event).data(data));}catch(IOException|IllegalStateException ex){connections.forEach((user,set)->{if(set.contains(e))remove(user,e);});}}private void remove(UUID user,SseEmitter e){connections.computeIfPresent(user,(_,set)->{set.remove(e);return set.isEmpty()?null:set;});}}
